def say(self, message, channel=None):
        if message is None:
            log.warning("message=None passed to Bot::say()")
            return

        if self.silent:
            return

        message = utils.clean_up_message(message)
        self.privmsg(message[:510], channel)

def whisper(bot, message, **rest):
        if not message:
            return False

        msg_args = message.split(" ")
        if len(msg_args) > 1:
            username = msg_args[0]
            rest = " ".join(msg_args[1:])
            bot.whisper_login(username, rest)

